        n++;
    }
    while (true) {
        boolean prime = true;
        if (n < 2) {
            prime = false;
        } else if (n == 2 || n == 3) {
            prime = true;
        } else if (n % 2 == 0 || n % 3 == 0) {
            prime = false;
        } else {
            int limit = (int) Math.sqrt(n);
            for (int i = 5; i <= limit; i += 6) {
                if (n % i == 0 || n % (i + 2) == 0) {
                    prime = false;
                    break;
                }
            }
        }
        if (prime) {
