protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>(graph, new ArrayList<>(), new ArrayList<>(), 0);
    }
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    double weight = 0;
    Iterator<E> it = tour.iterator();
    E firstEdge = it.next();
    it.remove();
    V current = graph.getEdgeSource(firstEdge);
    vertexList.add(current);
    edgeList.add(firstEdge);
    weight += graph.getEdgeWeight(firstEdge);
    boolean directed = graph.getType().isDirected();
    while (!tour.isEmpty()) {
        boolean found = false;
        Iterator<E> iter = tour.iterator();
        while (iter.hasNext()) {
            E e = iter.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (directed) {
                if (src.equals(current)) {
                    current = tgt;
                    vertexList.add(current);
                    edgeList.add(e);
                    weight += graph.getEdgeWeight(e);
                    iter.remove();
                    found = true;
                    break;
                }
            } else {
                if (src.equals(current)) {
                    current = tgt;
                    vertexList.add(current);
                    edgeList.add(e);
                    weight += graph.getEdgeWeight(e);
                    iter.remove();
                    found = true;
                    break;
                } else if (tgt.equals(current)) {
                    current = src;
                    vertexList.add(current);
                    edgeList.add(e);
                    weight += graph.getEdgeWeight(e);
                    iter.remove();
                    found = true;
                    break;
                }
            }
        }
        if (!found) {
            break;
        }
    }
    return new DefaultGraphPath<>(graph, vertexList, edgeList, weight);
