public static String applyRelativePath(String path,String relativePath){
    if (path == null || relativePath == null) {
        return null;
    }
    // Split the base path and relative path into components
    String[] baseParts = path.split("/");
    String[] relParts = relativePath.split("/");
    // Use a list as a stack to build the resulting path
    java.util.List<String> stack = new java.util.ArrayList<>();
    // Add base path components to the stack (ignore empty parts)
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    // Process relative path components
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    // Build the final path string
    StringBuilder sb = new StringBuilder();
    boolean leadingSlash = path.startsWith("/");
    for (int i = 0; i < stack.size(); i++) {
        if (i == 0 && leadingSlash) {
            sb.append('/');
        } else {
            sb.append('/');
        }
        sb.append(stack.get(i));
    }
    // Handle case where result is empty but original had leading slash
    if (sb.length() == 0 && leadingSlash) {
        sb.append('/');
    }
    return sb.toString();
}<|return|>

