public int readTag() throws IOException {
    try {
        if (!buffer.hasRemaining()) {
            return 0;
        }
        int result = 0;
        int shift = 0;
        while (true) {
            byte b = buffer.get();
            result |= (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                break;
            }
            shift += 7;
            if (shift > 35) {
                throw new IOException("Malformed varint");
            }
        }
        return result;
    } catch (java.nio.BufferUnderflowException e) {
        return 0;
    }
}<|return|>

