List<ThreadSnapshot> function (File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException { 
    List<ThreadSnapshot> result = new ArrayList<>(); 
    if (file == null || !file.exists() || !file.isFile()) { 
        return result; 
    } 
    try (BufferedReader br = new BufferedReader(new FileReader(file))) { 
        String line; 
        while ((line = br.readLine()) != null) { 
            if (line.trim().isEmpty()) continue; 
            ThreadSnapshot snapshot; 
            try { 
                snapshot = ThreadSnapshot.parse(line); 
            } catch (Exception e) { 
                continue; 
            } 
            if (timeRanges == null || timeRanges.isEmpty()) { 
                result.add(snapshot); 
            } else { 
                long ts = snapshot.getTimestamp(); 
                for (ProfileAnalyzeTimeRange range : timeRanges) { 
                    if (range == null) continue; 
                    if (ts >= range.getStart() && ts <= range.getEnd()) { 
                        result.add(snapshot); 
                        break; 
                    } 
                } 
            } 
        } 
    } 
    return result; 
}<|return|>
